## Why This Is Asked
This question tests the ability to design a practical data structure and reason about block balancing in edit-heavy scenarios.

## Key Concepts
- **Sqrt decomposition**: Partition data into fixed-size blocks for efficient range queries
- **Per-block sums**: Enable O(1) block-level aggregation during rangeSum operations
- **Amortized balance**: Split/merge operations maintain block sizes within bounds, ensuring O(√n) amortized time per update
- **Edge-case handling**: Proper merge/split logic prevents pathological degradation

## Code Example
```javascript
class SqrtArray {
  constructor() {
    this.blocks = [];
    this.B = 2;
  }

  _getBlock(index) {
    let count = 0;
    for (const block of this.blocks) {
      if (index < count + block.length) return block;
      count += block.length;
    }
    throw new Error('Index out of bounds');
  }

  insertAt(index, value) {
    const block = this._getBlock(index);
    block.push(value);
    block.sum += value;
    if (block.length > 2 * this.B) this._split(block);
  }

  eraseAt(index) {
    const block = this._getBlock(index);
    block.splice(index, 1);
    block.sum -= value;
    if (block.length < this.B / 2) this._merge(block);
  }

  rangeSum(l, r) {
    let sum = 0;
    let count = 0;
    for (const block of this.blocks) {
      const blockStart = count;
      const blockEnd = count + block.length - 1;
      if (r < blockStart || l > blockEnd) { count += block.length; continue; }
      const start = Math.max(l, blockStart);
      const end = Math.min(r, blockEnd);
      if (start === blockStart && end === blockEnd) sum += block.sum;
      else for (let i = start; i <= end; i++) sum += block[i];
      count += block.length;
    }
    return sum;
  }

  _split(block) {
    const mid = Math.floor(block.length / 2);
    const newBlock = { arr: block.arr.splice(mid), sum: newBlock.arr.reduce((a,b)=>a+b,0) };
    block.sum = block.arr.reduce((a,b)=>a+b,0);
    const idx = this.blocks.indexOf(block);
    this.blocks.splice(idx + 1, 0, newBlock);
  }

  _merge(block) {
    const idx = this.blocks.indexOf(block);
    const neighbor = idx > 0 ? this.blocks[idx - 1] : this.blocks[idx + 1];
    const [small, big] = neighbor.length > block.length ? [block, neighbor] : [neighbor, block];
    big.arr.push(...small.arr);
    big.sum += small.sum;
    this.blocks.splice(this.blocks.indexOf(small), 1);
  }
}
```

## Why This Is Asked
Maintaining the median under dynamic inserts and deletes is a common, practical data-structure task that tests understanding of balanced structures and handling edge cases with duplicates.

## Key Concepts
- Median of a dynamic multiset
- Heaps: max-heap for lower half, min-heap for upper half
- Lazy deletion via hashmap to avoid O(n) removal
- Balancing logic and handling duplicates with reference counting

## Code Example
```javascript
class MedianSet {
  constructor() {
    this.low = new MaxHeap();
    this.high = new MinHeap();
    this.delLow = new Map();
    this.delHigh = new Map();
  }

  _prune() {
    while (this.low.size() > 0 && this.delLow.has(this.low.peek())) {
      const count = this.delLow.get(this.low.peek()) - 1;
      if (count <= 0) this.delLow.delete(this.low.peek());
      else this.delLow.set(this.low.peek(), count);
      this.low.pop();
    }
    while (this.high.size() > 0 && this.delHigh.has(this.high.peek())) {
      const count = this.delHigh.get(this.high.peek()) - 1;
      if (count <= 0) this.delHigh.delete(this.high.peek());
      else this.delHigh.set(this.high.peek(), count);
      this.high.pop();
    }
  }

  _rebalance() {
    if (this.low.size() > this.high.size() + 1) {
      this.high.push(this.low.pop());
    } else if (this.high.size() > this.low.size() + 1) {
      this.low.push(this.high.pop());
    }
  }

  insertScore(x) {
    if (this.low.size() === 0 || x <= this.low.peek()) {
      this.low.push(x);
    } else {
      this.high.push(x);
    }
    this._rebalance();
  }

  removeScore(x) {
    if (this.low.size() > 0 && x <= this.low.peek()) {
      const count = this.delLow.get(x) || 0;
      this.delLow.set(x, count + 1);
    } else {
      const count = this.delHigh.get(x) || 0;
      this.delHigh.set(x, count + 1);
    }
    this._prune();
    this._rebalance();
  }

  getMedian() {
    this._prune();
    if (this.low.size() > this.high.size()) return this.low.peek();
    if (this.high.size() > this.low.size()) return this.high.peek();
    return (this.low.peek() + this.high.peek()) / 2;
  }
}
```

